const DAILY_BUDGET = $('call limit variable').first().json.call_limit;

// 1. Active calls
const activeCalls = $('Get new calls count').first().json["active-calls-number"];

// 2. New calls available from current input
const newAvailable = $input.all().filter(item => item.json && Object.keys(item.json).length > 0).length;

// Allocate within budget: active first, then new, then follow-up takes the rest
const budgetAfterActive = Math.max(0, DAILY_BUDGET - activeCalls);
const newCalls          = Math.min(newAvailable, budgetAfterActive);
const followupCalls     = Math.max(0, budgetAfterActive - newCalls);

const totalCalls = activeCalls + newCalls + followupCalls;

return [{
  json: {
    activeCalls,
    newCalls,
    followupCalls,
    totalCalls
  }
}];

