const result = [];
const seen = new Set();

for (const item of $input.all()) {
  // Skip empty items (no json, or json with no keys)
  if (!item.json || Object.keys(item.json).length === 0) {
    continue;
  }

  let phone = (item.json.phone_number || '').replace(/\D/g, '');
  // Normalize to E.164 format (+1XXXXXXXXXX)
  if (phone.length === 11 && phone.startsWith('1')) {
    // Already has US country code → just add +
    phone = '+' + phone;
  } else if (phone.length === 10) {
    // No country code → add +1
    phone = '+1' + phone;
  } else {
    // Can't normalize → keep original
    phone = item.json.phone_number;
  }

  // Skip if we've already seen this phone number
  if (seen.has(phone)) {
    continue;
  }
  seen.add(phone);

  result.push({
    json: {
      ...item.json,
      phone_number: phone
    }
  });
}
return result;

