function sanitizeString(value) {
  if (typeof value !== 'string') return value;
  return value
    .replace(/[\x00-\x1F\x7F]/g, ' ')
    .trim();
}

function sanitizeObject(obj) {
  if (obj === null || obj === undefined) return obj;
  if (typeof obj === 'string') return sanitizeString(obj);
  if (Array.isArray(obj)) return obj.map(sanitizeObject);
  if (typeof obj === 'object') {
    const cleaned = {};
    for (const [key, value] of Object.entries(obj)) {
      cleaned[key] = sanitizeObject(value);
    }
    return cleaned;
  }
  return obj;
}

function isValidUSPhone(phone) {
  if (!phone || typeof phone !== 'string') return false;

  const digits = phone.replace(/\D/g, '');

  let areaCode, exchange;

  if (digits.length === 11 && digits[0] === '1') {
    areaCode = digits.slice(1, 4);
    exchange = digits.slice(4, 7);
  } else if (digits.length === 10) {
    areaCode = digits.slice(0, 3);
    exchange = digits.slice(3, 6);
  } else {
    return false;
  }

  if (!/^[2-9]\d{2}$/.test(areaCode)) return false;
  if (!/^[2-9]\d{2}$/.test(exchange)) return false;

  const fakeAreaCodes = new Set(['999', '000', '111', '222', '333', '444', '555', '666', '777']);
  if (fakeAreaCodes.has(areaCode)) return false;

  return true;
}

let data = items.map(item => item.json);

let cleanedData = data.filter(obj => Object.keys(obj).length > 0);

cleanedData = cleanedData.filter(obj => {
