const beforeVerify = $('Fix phone number format').all().map(item => item.json);
const afterVerify = $input.all().map(item => item.json);

// Build a map of email → verify result
const verifyMap = new Map();
afterVerify.forEach(item => {
  if (item.overdue_requests && item.overdue_requests.length > 0) {
    // Get email from first overdue request
    const email = item.overdue_requests[0]?.requestor_email;
    if (email) verifyMap.set(email, item);
  }
});

// Find items from beforeVerify whose email has no valid verify result
const failedItems = beforeVerify.filter(item => {
  return !verifyMap.has(item.requestor_email);
});

console.log(`Total in: ${beforeVerify.length}`);
console.log(`Total out (non-empty): ${verifyMap.size}`);
console.log(`Failed: ${failedItems.length}`);
console.log(`Failed emails: ${failedItems.map(i => i.requestor_email).join(', ')}`);

return failedItems.length > 0
  ? failedItems.map(json => ({ json }))
  : [{ json: { message: 'All emails passed', total: beforeVerify.length } }];

const groups = new Map();

for (const item of $input.all()) {
  // Skip empty responses
  if (!item.json || !item.json.overdue_requests || item.json.overdue_requests.length === 0) continue;

  for (const requestor of item.json.overdue_requests) {
    if (!requestor.requestor_contact_number || !requestor.request_ids?.length) continue;

    // Normalize phone to E.164
    let phone = String(requestor.requestor_contact_number).replace(/\D/g, '');
    if (phone.length === 10) phone = '+1' + phone;
    else if (phone.length === 11 && phone.startsWith('1')) phone = '+' + phone;
    else phone = '+' + phone;

    // Set up group if first time seeing this phone
    if (!groups.has(phone)) {
      groups.set(phone, {
        phone_number: phone,
        requestor_name: requestor.requestor_name,
        requestor_email: requestor.requestor_email,
        organization_name: requestor.requestor_organization_name,
        provider_name: requestor.provider_name,
        organization_service_level: requestor.organization_service_level,
        status: 'new',
        follow_up_count: 0,
        request_count: 0,
        total_invoice_amount: 0,
        request_ids: [],
        invoice_amounts: [],
        days_past_due_list: [],
        patient_names: []
      });
    }

    // Push each invoice into the group
    const group = groups.get(phone);
    for (const invoice of requestor.request_ids) {
      group.request_ids.push(invoice.request_id);
      group.invoice_amounts.push(invoice.invoice_amount);
      group.days_past_due_list.push(invoice.days_past_due);
      group.patient_names.push(invoice.patient_name);
      group.total_invoice_amount += invoice.invoice_amount;
    }
  }
}

// Finalize counts, stringify arrays for DataTable
for (const group of groups.values()) {
  group.request_count = group.request_ids.length;
  group.total_invoice_amount = Math.round(group.total_invoice_amount * 100) / 100;
  group.request_ids = group.request_ids.join(', ');
  group.invoice_amounts = JSON.stringify(group.invoice_amounts);
  group.days_past_due_list = JSON.stringify(group.days_past_due_list);
  group.patient_names = group.patient_names.join(', '); 
}

return Array.from(groups.values()).map(json => ({ json }));

// n8n Code Node — Mode: "Run Once for All Items"
//
// Handles both possible input shapes:
//  1) Previous node produced separate n8n items (expected case)
//  2) Previous node produced ONE item whose .json is a raw array of objects
//     (happens when an HTTP Request / webhook node returns a JSON array
//     without "Split Into Items" turned on)
//
// LOGIC:
//  - request_id count >= 15 -> ALL original fields kept, but request_ids,
//                               invoice_amounts, days_past_due_list, and
//                               patient_names are sliced down to their
//                               first 10 entries (as arrays)
//  - request_id count < 15  -> full record sent as-is, with those same
//                               four fields converted to full arrays
//
// Nothing is dropped — every record produces exactly one output item.

const LOW_THRESHOLD = 15;

// Helper: parse a comma-separated string field, optionally wrapped in [ ]
// e.g. "[25,81.72,20]" or "14609449, 14609631" -> ["25","81.72","20"]
function parseListField(raw, transform = (v) => v) {
  if (!raw) return [];
  return String(raw)
    .replace(/^\[|\]$/g, "") // strip leading/trailing brackets if present
    .split(",")
    .map((s) => s.trim())
    .filter((s) => s.length > 0)
    .map(transform);
}

// Step 1: flatten everything into a plain list of record objects,
// regardless of which shape they arrived in.
const records = [];
for (const item of $input.all()) {
  if (Array.isArray(item.json)) {
    records.push(...item.json); // case 2: unwrap the array
  } else {
    records.push(item.json); // case 1: already a single record
  }
}

// Step 2: build output based on the count of request ids
const output = [];
for (const data of records) {
  const idsArray = parseListField(data.request_ids);
  const invoiceAmountsArray = parseListField(data.invoice_amounts, (v) => parseFloat(v));
  const daysPastDueArray = parseListField(data.days_past_due_list, (v) => parseInt(v, 10));
  const patientNamesArray = parseListField(data.patient_names);

  const count = idsArray.length;
  const isReduced = count >= LOW_THRESHOLD;

  output.push({
    json: {
      ...data, // keep ALL original fields: phone_number, requestor_name,
                // requestor_email, organization_name, provider_name,
                // organization_service_level, status, follow_up_count,
                // request_count, total_invoice_amount, etc.
      route: "detail",
      request_id_count: count,
      summary_message: `This request contains ${count} record request(s).`,
      request_ids: isReduced ? idsArray.slice(0, 10) : idsArray,
      invoice_amounts: isReduced ? invoiceAmountsArray.slice(0, 10) : invoiceAmountsArray,
      days_past_due_list: isReduced ? daysPastDueArray.slice(0, 10) : daysPastDueArray,
      patient_names: isReduced ? patientNamesArray.slice(0, 10) : patientNamesArray,
    },
  });
}

return output;
